import { EChart, type EChartSetup } from "@/components/ui/echart"
import "echarts-gl"

// Adapted from the Apache ECharts example "Sphere Parametric Surface" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=sphere-parametric-surface
const setup: EChartSetup = () => {
  let option: any
  option = {
    tooltip: {},
    visualMap: {
      show: false,
      dimension: 2,
      min: -1,
      max: 1,
      inRange: {
        color: [
          '#313695',
          '#4575b4',
          '#74add1',
          '#abd9e9',
          '#e0f3f8',
          '#ffffbf',
          '#fee090',
          '#fdae61',
          '#f46d43',
          '#d73027',
          '#a50026'
        ]
      }
    },
    xAxis3D: {},
    yAxis3D: {},
    zAxis3D: {},
    grid3D: {},
    series: [
      {
        type: 'surface',
        parametric: true,
        // shading: 'albedo',
        parametricEquation: {
          u: {
            min: -Math.PI,
            max: Math.PI,
            step: Math.PI / 20
          },
          v: {
            min: 0,
            max: Math.PI,
            step: Math.PI / 20
          },
          x: function (u: any, v: any) {
            return Math.sin(v) * Math.sin(u);
          },
          y: function (u: any, v: any) {
            return Math.sin(v) * Math.cos(u);
          },
          z: function (u: any, v: any) {
            return Math.cos(v);
          }
        }
      }
    ]
  };
  return option
}

export function EchartsSphereParametricSurface() {
  return <EChart setup={setup} />
}
